float hash21(vec2 p) {
    return fract(sin(dot(p, vec2(141.13, 289.97))) * 43758.5453);
}

// Function to get square grid coordinates and center
vec4 getSquare(vec2 p) {
    vec2 cell = floor(p); // Get square grid cell
    vec2 center = cell + 0.5; // Center of the square cell
    vec2 relPos = p - center; // Position relative to the center
    return vec4(relPos, center); // Return relative position and center
}

// Function to calculate the edge distance for a square
float squareEdgeDist(vec2 p) {
    p = abs(p);
    return max(p.x, p.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Aspect-corrected screen coordinates
    vec2 u = (fragCoord - iResolution.xy * 0.5) / iResolution.y;

    // Scale and translate the coordinates
    vec4 square = getSquare(u * 5.0);

    // Edge distance for the square
    float eDist = squareEdgeDist(square.xy);

    // Background with dark borders
    vec3 col = mix(vec3(1.0), vec3(0.0), smoothstep(0.0, 0.03, eDist - 0.5 + 0.04));
    fragColor = vec4(col, 1.0);
}
